from pathlib import Path
exec(Path(__file__).with_name('test-map-browser.py').read_text(encoding='utf-8').split("cmd('Emulation.setDeviceMetricsOverride'")[0])
cmd('Page.enable');cmd('Network.enable');cmd('Network.setCacheDisabled',{'cacheDisabled':True})
cmd('Page.addScriptToEvaluateOnNewDocument',{'source':'window.errors=[];window.addEventListener("error",e=>errors.push(e.message));'})
cmd('Page.navigate',{'url':base+'compare.html'})
wait("typeof KdramaCompare!=='undefined' && document.getElementById('compare-photo').onchange")
ev("window.byId=id=>document.getElementById(id);window.makeFile=async name=>{const c=document.createElement('canvas');c.width=200;c.height=100;c.getContext('2d').fillRect(0,0,100,100);return new File([await new Promise(r=>c.toBlob(r))],name,{type:'image/png'})};void 0")
ev("(async()=>{for(const kind of ['scene','photo']){const d=new DataTransfer();d.items.add(await makeFile(kind+'.png'));byId('compare-'+kind).closest('label').dispatchEvent(new DragEvent('drop',{dataTransfer:d,bubbles:true,cancelable:true}));}})()")
wait("!document.getElementById('compare-download').disabled")
ev("byId('compare-mode').value='vertical';byId('compare-mode').dispatchEvent(new Event('input'));byId('compare-gap').value='30';byId('compare-gap').dispatchEvent(new Event('input'));")
assert ev("byId('compare-preview').height>byId('compare-preview').width")
assert ev("(async()=>{const b=await new Promise(r=>byId('compare-preview').toBlob(r,'image/png'));return b.type==='image/png'&&b.size>1000})()")
ev("byId('compare-mode').value='overlay';byId('compare-mode').dispatchEvent(new Event('input'));byId('compare-divider').value='0';byId('compare-divider').dispatchEvent(new Event('input'))")
assert ev("!byId('compare-divider-label').hidden && byId('compare-gap').disabled")
ev("(async()=>{const d=new DataTransfer();d.items.add(await makeFile('paste.png'));document.dispatchEvent(new ClipboardEvent('paste',{clipboardData:d,bubbles:true,cancelable:true}));})()")
# Verify actual exported blend pixels, then drag a zoomed image with real pointer events.
ev("(async()=>{for(const [kind,color]of [['scene','#ff0000'],['photo','#0000ff']]){const c=document.createElement('canvas');c.width=c.height=200;const x=c.getContext('2d');x.fillStyle=color;x.fillRect(0,0,200,200);const d=new DataTransfer();d.items.add(new File([await new Promise(r=>c.toBlob(r))],kind+'.png',{type:'image/png'}));byId('compare-'+kind).files=d.files;byId('compare-'+kind).dispatchEvent(new Event('change'));}})()")
time.sleep(.3)
ev("byId('compare-mode').value='blend';byId('compare-mode').dispatchEvent(new Event('input'));byId('compare-opacity').value='50';byId('compare-opacity').dispatchEvent(new Event('input'))")
assert ev("(()=>{const p=byId('compare-preview').getContext('2d').getImageData(10,10,1,1).data;return p[0]>=126&&p[0]<=129&&p[1]===0&&p[2]>=126&&p[2]<=129})()")
ev("byId('compare-photoZoom').value='200';byId('compare-photoZoom').dispatchEvent(new Event('input'));byId('compare-preview').scrollIntoView({block:'center'})")
rect=ev("(()=>{const r=byId('compare-preview').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+30}})()")
cmd('Input.dispatchMouseEvent',{'type':'mousePressed','x':rect['x'],'y':rect['y'],'button':'left','clickCount':1})
cmd('Input.dispatchMouseEvent',{'type':'mouseMoved','x':rect['x']+25,'y':rect['y']+10,'button':'left','buttons':1})
cmd('Input.dispatchMouseEvent',{'type':'mouseReleased','x':rect['x']+25,'y':rect['y']+10,'button':'left','clickCount':1})
assert ev("Number(byId('compare-x').value)<50")
ev("byId('compare-mode').value='overlay';byId('compare-mode').dispatchEvent(new Event('input'))")
cmd('Page.reload');wait("document.getElementById('compare-photo')?.onchange")
assert ev("document.getElementById('compare-mode').value==='overlay' && document.getElementById('compare-download').disabled")
cmd('Emulation.setDeviceMetricsOverride',{'width':390,'height':844,'deviceScaleFactor':1,'mobile':True})
assert ev('document.documentElement.scrollWidth<=innerWidth+1')
assert ev('errors.length===0'),ev('errors')
print('Comparison drop/paste, layout, export pixels, settings recovery and mobile layout passed.')
